def solve(g):
    H,W=len(g),len(g[0])
    fives=[(i,j) for i,r_ in enumerate(g) for j,v in enumerate(r_) if v==5]
    def nb(p):
        return any(0<=p[0]+a<H and 0<=p[1]+b<W and g[p[0]+a][p[1]+b]!=0 for a in(-1,0,1) for b in(-1,0,1))
    anchor=next(p for p in fives if nb(p))
    offs=[(r-anchor[0],c-anchor[1],g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=0 and (r,c)!=anchor]
    out=[r[:] for r in g]
    for s in (p for p in fives if p!=anchor):
        out[s[0]][s[1]]=0
        for dr,dc,v in offs:
            sr,sc=s[0]+dr,s[1]+dc
            if 0<=sr<H and 0<=sc<W: out[sr][sc]=v
    return out
